# JavaScript Coding Solution (Python demonstration)
 def double_elements(arr):
  # map equivalent: list comprehension
  return list(map(lambda x: x * 2, arr))

 # JavaScript equivalent:
 # function doubleElements(arr) { return arr.map(x => x * 2); }

 print(double_elements([1, 2, 3, 4, 5])) # [2, 4, 6, 8, 10]
 # Output:
 # [2, 4, 6, 8, 10]

# JavaScript Coding Solution (Python demonstration)
 def filter_evens(arr):
  return list(filter(lambda x: x % 2 == 0, arr))

 # JavaScript equivalent:
 # function filterEvens(arr) { return arr.filter(x => x % 2 === 0); }

 print(filter_evens([1, 2, 3, 4, 5, 6])) # [2, 4, 6]
 # Output:
 # [2, 4, 6]

