# JavaScript groupBy Solution (Python demonstration)
 def group_by(arr, key):
  result = {}
  for item in arr:
  group_key = item[key]
  if group_key not in result:
  result[group_key] = []
  result[group_key].append(item)
  return result

 # JavaScript equivalent:
 # function groupBy(arr, key) {
 # return arr.reduce((acc, item) => {
 # (acc[item[key]] = acc[item[key]] || []).push(item);
 # return acc;
 # }, {});
 # }

 people = [
  {'name': 'Alice', 'dept': 'Engineering'},
  {'name': 'Bob', 'dept': 'Marketing'},
  {'name': 'Carol', 'dept': 'Engineering'}
 ]
 print(group_by(people, 'dept'))
 # Output:
 # {'Engineering': [{'name': 'Alice', ...}, {'name': 'Carol', ...}],
 # 'Marketing': [{'name': 'Bob', ...}]}

# JavaScript IIFE Solution (Python class-based demonstration)

 # Simulates JS IIFE pattern: (function(){ ... })()
 class PrivateCounter:
  def __init__(self):
  self.__count = 0 # Private variable (closure in JS)

  def increment(self):
  self.__count += 1

  def get(self):
  return self.__count

 # JavaScript equivalent:
 # const counter = (function() {
 # let count = 0;
 # return { increment: () => count++, get: () => count };
 # })();

 counter = PrivateCounter()
 counter.increment()
 counter.increment()
 print(counter.get()) # 2
 # Output:
 # 2

# JavaScript Array.find() Solution (Python demonstration)
 def find_admin(users):
  # find() returns first match
  return next((u for u in users if u.get('role') == 'admin'), None)

 # JavaScript equivalent:
 # function findAdmin(users) {
 # return users.find(u => u.role === 'admin');
 # }

 users = [
  {'name': 'Alice', 'role': 'user'},
  {'name': 'Bob', 'role': 'admin'},
  {'name': 'Carol', 'role': 'user'},
 ]
 admin = find_admin(users)
 print(admin) # {'name': 'Bob', 'role': 'admin'}
 # Output:
 # {'name': 'Bob', 'role': 'admin'}

