 print(get_type([1,2,3])) # list
 print(get_type({'a': 1})) # dict
 print(get_type(None)) # NoneType
 # Output:
 # int
 # str
 # list
 # dict
 # NoneType

# JavaScript Debounce Solution (Python demonstration using threading)
 import threading

 def debounce(fn, delay_ms):
  timer = [None]

  def debounced(*args, **kwargs):
  if timer[0]:
  timer[0].cancel()
  timer[0] = threading.Timer(delay_ms / 1000, lambda: fn(*args, **kwargs))
  timer[0].start()

  return debounced

 # JavaScript equivalent:
 # function debounce(fn, delay) {
 # let timer;
 # return function(...args) {
 # clearTimeout(timer);
 # timer = setTimeout(() => fn(...args), delay);
 # };
 # }

 def search(query):
  print(f'Searching for: {query}')

 debounced_search = debounce(search, 300)
 # In real use, rapid calls are delayed
 debounced_search('hello') # would debounce in a browser
 import time; time.sleep(0.5)
 # Output:
 # Searching for: hello

