 buggy = '''async function getUser() {
  const data = fetch('/api/user'); // BUG: missing await
  console.log(data); // Logs Promise object, not data
 }'''

 fixed = '''async function getUser() {
  try {
  const response = await fetch('/api/user'); // Fixed: added await
  const data = await response.json(); // Also await .json()
  console.log(data);
  } catch (error) {
