# JavaScript EventEmitter Solution (Python demonstration)
 class EventEmitter:
  def __init__(self):
  self._events = {}

  def on(self, event, callback):
  if event not in self._events:
  self._events[event] = []
  self._events[event].append(callback)

  def emit(self, event, *args):
  for cb in self._events.get(event, []):
  cb(*args)

 # JavaScript equivalent:
 # class EventEmitter {
 # constructor() { this.events = {}; }
 # on(event, cb) { (this.events[event] = this.events[event]||[]).push(cb); }
 # emit(event, ...args) { (this.events[event]||[]).forEach(cb => cb(...args)); }
 # }

 emitter = EventEmitter()
 emitter.on('data', lambda msg: print(f'Received: {msg}'))
 emitter.emit('data', 'Hello World')
 emitter.emit('data', 'Second message')
 # Output:
 # Received: Hello World
 # Received: Second message

