# JavaScript Callback Solution (Python demonstration)
 import time

 def read_file(filename, callback):
  # Simulate async file read
  time.sleep(0.1)
  content = f'Contents of {filename}'
  callback(None, content) # error-first callback pattern

 def on_file_read(error, data):
  if error:
  print(f'Error: {error}')
  return
  print(f'File data: {data}')

 # JavaScript equivalent:
