# API Coding Solution
 # Simulate in-memory database
 users_db = {
  1: {'id': 1, 'name': 'Alice', 'email': 'alice@example.com', 'role': 'user'},
  2: {'id': 2, 'name': 'Bob', 'email': 'bob@example.com', 'role': 'admin'},
 }

 def put_user(user_id, new_data):
  if user_id not in users_db:
  return {'status': 404, 'error': 'User not found'}

  # PUT fully replaces the resource
  updated = {'id': user_id, **new_data}
  users_db[user_id] = updated
  return {'status': 200, 'data': updated}

 response = put_user(1, {'name': 'Alice Smith', 'email': 'alice.s@example.com', 'role': 'moderator'})
 print(f'Status: {response["status"]}')
 print(f'Updated: {response["data"]}')
 # Output:
 # Status: 200
 # Updated: {'id': 1, 'name': 'Alice Smith', 'email': 'alice.s@example.com', 'role': 'moderator'}

# API Coding Solution
 users_db = {
  1: {'id': 1, 'name': 'Alice', 'email': 'alice@example.com', 'role': 'user'}
 }

 def patch_user(user_id, partial_data):
  if user_id not in users_db:
  return {'status': 404, 'error': 'User not found'}

  # PATCH only updates specified fields
  users_db[user_id].update(partial_data)
  return {'status': 200, 'data': users_db[user_id]}

 # Only update email
 response = patch_user(1, {'email': 'new.alice@example.com'})
 print(f'Status: {response["status"]}')
 print(f'Patched: {response["data"]}')
 # Output:
 # Status: 200
 # Patched: {'id': 1, 'name': 'Alice', 'email': 'new.alice@example.com', 'role': 'user'}

# API Coding Solution
 def build_url(base_url, path_params=None, query_params=None):
  url = base_url
  # Add path parameters
  if path_params:
  for key, value in path_params.items():
  url = url.replace(f'{{{key}}}', str(value))
  # Add query string
  if query_params:
  qs = '&'.join(f'{k}={v}' for k, v in query_params.items())
  url += '?' + qs
  return url

 # Test
 url1 = build_url(
  'https://api.example.com/users/{id}/posts',
  path_params={'id': 42}
 )
 url2 = build_url(
  'https://api.example.com/products',
  query_params={'page': 1, 'limit': 10, 'sort': 'price'}
 )
 print(url1)
 print(url2)
 # Output:
 # https://api.example.com/users/42/posts
 # https://api.example.com/products?page=1&limit=10&sort=price

