# API Coding Solution - Request Validation
 def validate_user_payload(payload):
  errors = []
  required_fields = ['name', 'email', 'password']

  for field in required_fields:
  if field not in payload or not payload[field]:
  errors.append(f'{field} is required')

  if 'email' in payload and '@' not in str(payload.get('email', '')):
  errors.append('email must be a valid email address')

  if 'password' in payload and len(str(payload.get('password', ''))) < 8:
  errors.append('password must be at least 8 characters')

  if errors:
  return {'status': 400, 'errors': errors}
  return {'status': 200, 'message': 'Payload is valid'}

 # Valid payload
 print(validate_user_payload({'name': 'Alice', 'email': 'alice@ex.com', 'password': 'secret123'}))
 # Invalid payload
 print(validate_user_payload({'name': '', 'email': 'notanemail', 'password': '123'}))
 # Output:
 # {'status': 200, 'message': 'Payload is valid'}
 # {'status': 400, 'errors': ['name is required', 'email must be a valid...', 'password must be...']}
